class InputCell:
    def __init__(self, initial_value):
        self._value = initial_value
        self._observers = []

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        self._propagate()

    def _add_observer(self, observer):
        self._observers.append(observer)

    def _propagate(self):
        # Collect every compute cell that (transitively) depends on this
        # input, i.e. everything reachable downstream through observers.
        affected = set()
        stack = list(self._observers)
        while stack:
            cell = stack.pop()
            if cell in affected:
                continue
            affected.add(cell)
            stack.extend(cell._observers)

        if not affected:
            return

        # Topologically order the affected cells (Kahn's algorithm) so that a
        # cell is recomputed only after all of its affected inputs have been.
        for cell in affected:
            cell._in_degree = sum(1 for i in cell._inputs if i in affected)

        queue = [cell for cell in affected if cell._in_degree == 0]
        while queue:
            cell = queue.pop(0)
            cell._recompute()
            for observer in cell._observers:
                if observer in affected:
                    observer._in_degree -= 1
                    if observer._in_degree == 0:
                        queue.append(observer)


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self._inputs = inputs
        self._compute_function = compute_function
        self._observers = []
        self._callbacks = []
        self._value = self._compute_function([i.value for i in inputs])
        for i in inputs:
            i._add_observer(self)

    @property
    def value(self):
        return self._value

    def _add_observer(self, observer):
        self._observers.append(observer)

    def _recompute(self):
        old = self._value
        self._value = self._compute_function([i.value for i in self._inputs])
        if self._value != old:
            for callback in list(self._callbacks):
                callback(self._value)

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
